<?php
$linkCategoryList=query('SELECT c.id,c.name,COUNT(r.link_id) AS total FROM link_categories c LEFT JOIN link_category_relations r ON r.category_id=c.id GROUP BY c.id,c.name ORDER BY c.name')->fetchAll();$linkEdit=isset($_GET['edit_link'])?query('SELECT * FROM links WHERE id=?',[(int)$_GET['edit_link']])->fetch():null;$linkCategoryMode=isset($_GET['link_categories']);$linkEditorMode=isset($_GET['new_link'])||isset($_GET['edit_link']);
?>
<nav class="admin-subnav"><a href="/admin/links" class="<?=!$linkCategoryMode&&!$linkEditorMode?'active':''?>"><?=e(t('All links'))?></a><a href="/admin/links?new_link=1" class="<?=$linkEditorMode?'active':''?>"><?=e(t('Add link'))?></a><a href="/admin/links?link_categories=1" class="<?=$linkCategoryMode?'active':''?>"><?=e(t('Link categories'))?></a></nav>
<?php if($linkCategoryMode):?>
<section class="panel admin-panel"><h2><?=e(t('Link categories'))?></h2><p class="muted"><?=e(t('Link categories are independent from article categories. Deleting one keeps its links.'))?></p><form class="admin-inline-form" data-admin-action="link_category_save"><input name="name" aria-label="<?=e(t('Category name'))?>" placeholder="<?=e(t('Category name'))?>" maxlength="80" required><button class="button" type="submit"><?=e(t('Add category'))?></button></form><?php bulkToolbar('link_categories');?><div class="admin-table-wrap"><table class="admin-table taxonomy-table"><thead><tr><th class="select-cell"><?php selectionBox();?></th><th><?=e(t('Category name'))?></th><th><?=e(t('Links'))?></th><th><?=e(t('Actions'))?></th></tr></thead><tbody><?php foreach($linkCategoryList as $category):$formId='link-category-'.$category['id'];?><tr><td class="select-cell"><?php selectionBox((int)$category['id'],$category['name']);?></td><td><input form="<?=$formId?>" name="name" aria-label="<?=e(t('Category name'))?>" value="<?=e($category['name'])?>" maxlength="80" required></td><td><?=$category['total']?></td><td><form id="<?=$formId?>" data-admin-action="link_category_save" class="admin-row-actions"><input type="hidden" name="id" value="<?=$category['id']?>"><button class="button secondary" type="submit"><?=e(t('Save changes'))?></button><button class="square-danger" type="submit" data-action="link_category_delete" formnovalidate aria-label="<?=e(t('Delete'))?>"><?=icon('trash')?></button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<?php elseif($linkEditorMode):if(isset($_GET['edit_link'])&&!$linkEdit):?><section class="panel admin-panel"><?=e(t('Link not found.'))?></section><?php else:$selectedCategories=$linkEdit?array_column(linkCategories((int)$linkEdit['id']),'id'):[];?>
<section class="panel admin-panel"><h2><?=e(t($linkEdit?'Edit link':'Add link'))?></h2><form class="settings-form" data-admin-action="link_save"><input type="hidden" name="id" value="<?=e($linkEdit['id']??'')?>"><?php foreach(['name'=>'Name','url'=>'Web address','description'=>'Description','logo_url'=>'Logo URL'] as $field=>$label):?><label><?=e(t($label))?><input name="<?=$field?>" value="<?=e($linkEdit[$field]??'')?>" maxlength="<?=$field==='name'?200:($field==='description'?500:1000)?>" <?=in_array($field,['name','url'],true)?'required':''?> placeholder="<?=in_array($field,['url','logo_url'],true)?'https://…':''?>"></label><?php endforeach;?><fieldset class="link-category-fieldset"><legend><?=e(t('Link categories'))?></legend><?php foreach($linkCategoryList as $category):?><label class="menu-visible"><input type="checkbox" name="link_categories[]" value="<?=$category['id']?>" <?=in_array($category['id'],$selectedCategories,true)?'checked':''?>><?=e($category['name'])?></label><?php endforeach;?><a class="text-button" href="/admin/links?link_categories=1"><?=e(t('Manage link categories'))?></a></fieldset><button class="button" type="submit"><?=e(t('Save link'))?></button><p role="status"></p></form></section>
<?php endif;else:
$linkSearch=mb_substr(trim((string)($_GET['s']??'')),0,200);$linkFilter=max(0,(int)($_GET['link_category']??0));$linkWhere=' WHERE 1=1';$linkParams=[];if($linkSearch!==''){$linkWhere.=' AND (l.name LIKE ? OR l.url LIKE ? OR l.description LIKE ?)';$linkParams=array_fill(0,3,'%'.$linkSearch.'%');}if($linkFilter){$linkWhere.=' AND EXISTS(SELECT 1 FROM link_category_relations r WHERE r.link_id=l.id AND r.category_id=?)';$linkParams[]=$linkFilter;}$linkTotal=(int)query('SELECT COUNT(*) FROM links l'.$linkWhere,$linkParams)->fetchColumn();$linkPage=min(max(1,(int)($_GET['page']??1)),max(1,(int)ceil($linkTotal/20)));$linkOffset=($linkPage-1)*20;$linkList=query('SELECT l.* FROM links l'.$linkWhere." ORDER BY l.name,l.id LIMIT 20 OFFSET $linkOffset",$linkParams)->fetchAll();
?>
<section class="panel admin-panel"><div class="list-toolbar"><?php bulkToolbar('links');?><form class="admin-filters" action="/admin/links"><input name="s" aria-label="<?=e(t('Search links'))?>" placeholder="<?=e(t('Search links'))?>" value="<?=e($linkSearch)?>"><select name="link_category" aria-label="<?=e(t('Link categories'))?>"><option value="0"><?=e(t('All categories'))?></option><?php foreach($linkCategoryList as $category):?><option value="<?=$category['id']?>" <?=$linkFilter===$category['id']?'selected':''?>><?=e($category['name'])?></option><?php endforeach;?></select><button class="button"><?=e(t('Filter'))?></button></form></div><div class="admin-table-wrap"><table class="admin-table links-table"><thead><tr><th class="select-cell"><?php selectionBox();?></th><?php foreach(['Logo','Name','Web address','Description','Link categories','Actions'] as $label):?><th><?=e(t($label))?></th><?php endforeach;?></tr></thead><tbody><?php foreach($linkList as $link):?><tr><td class="select-cell"><?php selectionBox((int)$link['id'],$link['name']);?></td><td><?php if($link['logo_url']!==''):?><img class="link-logo" src="<?=e($link['logo_url'])?>" alt="" loading="lazy"><?php endif;?></td><td><strong><a href="/admin/links?edit_link=<?=$link['id']?>"><?=e($link['name'])?></a></strong></td><td><a href="<?=e($link['url'])?>" target="_blank" rel="noopener noreferrer"><?=e(absoluteSiteUrl($link['url']))?></a></td><td><?=e($link['description'])?></td><td><?=e(implode(', ',array_column(linkCategories((int)$link['id']),'name')))?></td><td><div class="admin-row-actions"><a href="/admin/links?edit_link=<?=$link['id']?>"><?=e(t('Edit'))?></a><form data-admin-action="link_delete"><input type="hidden" name="id" value="<?=$link['id']?>"><button type="submit" class="text-button"><?=e(t('Delete'))?></button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php if(!$linkList):?><p class="admin-empty"><?=e(t('No links found.'))?></p><?php endif;?><nav class="pagination"><span><?=$linkTotal?> · <?=$linkPage?> / <?=max(1,(int)ceil($linkTotal/20))?></span><?php foreach([-1=>'Previous',1=>'Next'] as $step=>$label):if($linkPage+$step<1||$linkPage+$step>ceil($linkTotal/20))continue;?><a href="<?=e('/admin/links?'.http_build_query(['s'=>$linkSearch,'link_category'=>$linkFilter,'page'=>$linkPage+$step]))?>"><?=e(t($label))?></a><?php endforeach;?></nav></section>
<?php endif;?>
